import{_ as r,D as o,c as n,I as a,a4 as e,o as i}from"./chunks/framework.CRCV4hx_.js";const v=JSON.parse('{"title":"Rates","description":"","frontmatter":{},"headers":[],"relativePath":"rates.md","filePath":"rates.md"}'),s={name:"rates.md"},l=e('<h1 id="rates" tabindex="-1">Rates <a class="header-anchor" href="#rates" aria-label="Permalink to &quot;Rates&quot;">​</a></h1><p>Rates are how Resrv handles multiple pricing and availability options on a single Entry. A common example is a hotel room type that you sell at a &quot;Standard&quot; rate, a discounted &quot;Non-refundable&quot; rate, and a &quot;Breakfast included&quot; rate, all sharing the same inventory but priced differently.</p><div class="info custom-block"><p class="custom-block-title">REPLACES ADVANCED &amp; CONNECTED AVAILABILITY</p><p>Rates are a new feature in v6 and replace the old &quot;Advanced availability&quot; (per-entry properties) and &quot;Connected availabilities&quot; features from v5. If you are upgrading an existing site, read <a href="./upgrading">Upgrading to v6</a> for the migration path.</p></div><h2 id="what-is-a-rate" tabindex="-1">What is a Rate? <a class="header-anchor" href="#what-is-a-rate" aria-label="Permalink to &quot;What is a Rate?&quot;">​</a></h2><p>A Rate is a record scoped to a <strong>Statamic collection</strong>, not to a single Entry. One collection can have many rates, and a rate can apply to every Entry in the collection or just a hand-picked few.</p><p>Each rate carries:</p><ul><li>A <strong>pricing type</strong>: its own prices, or prices derived from another rate.</li><li>An <strong>availability type</strong>: its own inventory pool, or a pool shared with another rate.</li><li>Optional <strong>restrictions</strong>: date window, booking lead time, and minimum/maximum stay.</li><li>An optional <strong>cancellation policy</strong>.</li><li>A <strong>published</strong> flag and a sort <strong>order</strong>.</li></ul><p>When an Entry has more than one published rate, your visitors get to pick which rate to book on the frontend.</p><h2 id="managing-rates" tabindex="-1">Managing rates <a class="header-anchor" href="#managing-rates" aria-label="Permalink to &quot;Managing rates&quot;">​</a></h2><p>Rates live in their own <strong>Rates</strong> section in the admin panel, under the Resrv navigation.</p>',10),d=e('<p>At the top of the screen you pick a <strong>collection</strong>. Only collections that use the <a href="./availability">Resrv Availability</a> field appear here.</p><p>Rates are shown as a <strong>two-level tree</strong>. Top-level (base or standalone) rates appear first, with any rates derived from them nested and indented underneath. Drag handles let you reorder rates within a level.</p><p>The list shows badges for each rate, such as a published/draft indicator, &quot;All entries&quot; (when the rate applies to the whole collection), a &quot;Non-refundable&quot; warning, and on parent rates a count of how many rates derive from them.</p><p>To create a rate, click <strong>Add rate</strong>. To edit one, click its title. Both open the rate panel.</p>',4),h=e('<h2 id="apply-to-all-vs-specific-entries" tabindex="-1">Apply to all vs specific entries <a class="header-anchor" href="#apply-to-all-vs-specific-entries" aria-label="Permalink to &quot;Apply to all vs specific entries&quot;">​</a></h2><p>In the <strong>General</strong> section, the <strong>Apply to all entries in collection</strong> switch controls where the rate is available:</p><ul><li><strong>On</strong>: the rate applies to every Entry in the collection.</li><li><strong>Off</strong>: an entry picker appears so you can select exactly which Entries the rate applies to. Use <strong>Select all</strong> / <strong>Remove all</strong> to manage the list quickly.</li></ul><p>The collection is fixed once a rate is created; you cannot move a rate to another collection later.</p><h2 id="pricing-type" tabindex="-1">Pricing type <a class="header-anchor" href="#pricing-type" aria-label="Permalink to &quot;Pricing type&quot;">​</a></h2><p>A rate&#39;s <strong>pricing type</strong> decides where its prices come from.</p><ul><li><strong>Independent</strong> (default): the rate has its own per-day prices. For a standard rate that also owns its inventory, prices come from the Entry&#39;s <a href="./availability">Availability calendar</a> rows for that rate.</li><li><strong>Relative</strong>: the rate has no prices of its own. It derives them from a <strong>base rate</strong> by applying a modifier.</li></ul><p>When you choose <strong>Relative</strong>, you set three modifier fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td>Modifier type</td><td><code>Percent</code> or <code>Fixed</code></td><td>Whether the adjustment is a percentage or a flat amount.</td></tr><tr><td>Modifier operation</td><td><code>Increase</code> or <code>Decrease</code></td><td>Whether the adjustment raises or lowers the base price.</td></tr><tr><td>Modifier amount</td><td>A number (no <code>%</code> character)</td><td>The amount or percentage to apply.</td></tr></tbody></table><p>Behaviour:</p><ul><li><strong>Percent</strong> raises or lowers the base price by that percentage. A <code>Percent</code> + <code>Decrease</code> modifier is capped at 100.</li><li><strong>Fixed</strong> adds or subtracts a flat amount <strong>per day</strong> (for a multi-day booking the amount is multiplied by the number of nights).</li><li>A decrease that would push the price below zero is floored at zero.</li></ul><div class="warning custom-block"><p class="custom-block-title">PRICING TYPE IS IMMUTABLE</p><p>The pricing type cannot be changed after a rate is created. If you need to switch between independent and relative pricing, delete the rate and recreate it.</p></div><p>A base rate used for relative pricing must be in the <strong>same collection</strong>, must be <strong>published</strong>, and must itself be an <strong>independent, non-shared</strong> rate. Relative and shared rates cannot be used as a base.</p><h2 id="availability-type" tabindex="-1">Availability type <a class="header-anchor" href="#availability-type" aria-label="Permalink to &quot;Availability type&quot;">​</a></h2><p>A rate&#39;s <strong>availability type</strong> decides where its inventory comes from.</p><ul><li><strong>Independent</strong> (default): the rate has its own inventory pool, stored against its rate in the Availability calendar.</li><li><strong>Shared</strong>: the rate does not own inventory. It shares the <strong>base rate&#39;s</strong> pool, so booking the shared rate decrements the base rate&#39;s availability. You can optionally cap how many units are bookable on the shared rate with <strong>Max available</strong>, even when the underlying pool is larger.</li></ul><p>When you choose <strong>Shared</strong>, a base rate is required (the same base-rate field serves both relative pricing and shared availability).</p><div class="warning custom-block"><p class="custom-block-title">AVAILABILITY TYPE IS IMMUTABLE</p><p>Like the pricing type, the availability type cannot be changed after a rate is created. Delete and recreate the rate to switch it.</p></div><h3 id="the-four-configurations" tabindex="-1">The four configurations <a class="header-anchor" href="#the-four-configurations" aria-label="Permalink to &quot;The four configurations&quot;">​</a></h3><p>Pricing type and availability type combine into four real-world setups:</p><table tabindex="0"><thead><tr><th>Pricing</th><th>Availability</th><th>Base rate</th><th>What it is</th></tr></thead><tbody><tr><td>Independent</td><td>Independent</td><td>Not required</td><td>A standalone rate with its own prices and its own inventory. This is the default.</td></tr><tr><td>Relative</td><td>Independent</td><td>Required</td><td>Own inventory, price derived from the base rate via a modifier.</td></tr><tr><td>Independent</td><td>Shared</td><td>Required</td><td>Shares the base rate&#39;s inventory, but prices are managed independently (see below).</td></tr><tr><td>Relative</td><td>Shared</td><td>Required</td><td>Shares the base rate&#39;s inventory <strong>and</strong> derives its price from the base rate.</td></tr></tbody></table><h2 id="independent-pricing-on-shared-rates" tabindex="-1">Independent pricing on shared rates <a class="header-anchor" href="#independent-pricing-on-shared-rates" aria-label="Permalink to &quot;Independent pricing on shared rates&quot;">​</a></h2><p>When a rate is <strong>Shared</strong> and uses <strong>Independent</strong> pricing, it shares the base rate&#39;s inventory but keeps its own prices. Those prices are entered in the Entry&#39;s <a href="./availability">Availability calendar</a>, not in the Rates screen, where you set a per-day price for the shared rate. (Editing the <em>inventory</em> of a shared rate is blocked, since that comes from the base rate.)</p><p>A <strong>Require price override</strong> switch controls what happens on dates where you haven&#39;t set a price for the shared rate:</p><ul><li><strong>On</strong>: dates without an explicit price for this rate are <strong>unavailable</strong>.</li><li><strong>Off</strong>: those dates fall back to the <strong>base rate&#39;s</strong> price.</li></ul><p>This switch only appears for rates that are Shared with Independent pricing.</p><h2 id="restrictions" tabindex="-1">Restrictions <a class="header-anchor" href="#restrictions" aria-label="Permalink to &quot;Restrictions&quot;">​</a></h2><p>The <strong>Restrictions</strong> section lets you limit when a rate can be booked. Every field is optional.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Date range</td><td>The rate is only bookable within this window. The check-in date must fall on or after the start, and the booking must end on or before the end date.</td></tr><tr><td>Min days before</td><td>Early-bird: bookable only at least this many days before the reservation starts. The global minimum still applies. Leave empty for no restriction.</td></tr><tr><td>Max days before</td><td>Last-minute: bookable only at most this many days before the reservation starts. Use <strong>0</strong> for same-day bookings only. Leave empty for no restriction.</td></tr><tr><td>Min stay</td><td>Minimum number of nights.</td></tr><tr><td>Max stay</td><td>Maximum number of nights.</td></tr></tbody></table><h2 id="cancellation-policy" tabindex="-1">Cancellation policy <a class="header-anchor" href="#cancellation-policy" aria-label="Permalink to &quot;Cancellation policy&quot;">​</a></h2><p>Each rate can declare its own cancellation policy in the <strong>Cancellation policy</strong> section. This layers on top of the global free-cancellation settings in your <a href="./configuration">configuration</a>.</p><p>The <strong>Cancellation policy</strong> select offers three choices:</p><ul><li><strong>Free cancellation until X days before</strong> (<code>free_cancellation</code>): free cancellation up to a number of days before check-in. A <strong>Free cancellation period</strong> input appears so you can set that number of days.</li><li><strong>Non-refundable</strong> (<code>non_refundable</code>): no free-cancellation window. The booking is always prepaid in full.</li><li><strong>Use global default</strong> (leave empty): the rate inherits the global <code>free_cancellation_period</code> setting, which is the v5 behaviour.</li></ul><p>A customer-facing label is rendered from this policy on availability results, the checkout sidebar, the reservation details, and the confirmation email, for example &quot;Free cancellation until Mon 03 Jun 2026&quot; or &quot;Non-refundable&quot;. If the policy resolves to no configured period, no label is shown.</p><div class="warning custom-block"><p class="custom-block-title">NON-REFUNDABLE ALWAYS CHARGES IN FULL</p><p>Non-refundable rates always require <strong>full payment at checkout</strong>, regardless of your deposit settings, and this holds even after a coupon is applied or removed.</p></div><p>The resolved policy is <strong>snapshotted onto the reservation at booking time</strong>, so later edits to the rate or to the global settings never change the terms an existing booking was made under. For multi-day bookings that span several rates, Resrv resolves a single strictest policy across them: any non-refundable part makes the whole booking non-refundable.</p><h2 id="published-flag-ordering" tabindex="-1">Published flag &amp; ordering <a class="header-anchor" href="#published-flag-ordering" aria-label="Permalink to &quot;Published flag &amp; ordering&quot;">​</a></h2><p>The <strong>Settings</strong> section has a <strong>Published</strong> switch. Unpublished (draft) rates are hidden on the frontend, so you can prepare a rate before making it bookable.</p><p>Ordering is controlled by dragging rates in the Rates list. The order you set there is the order rates appear in on the frontend rate selector.</p><div class="info custom-block"><p class="custom-block-title">DELETING RATES</p><p>A rate cannot be deleted while it is used as the base for another rate, or while it has active reservations. Remove or reassign those first.</p></div><h2 id="on-the-frontend" tabindex="-1">On the frontend <a class="header-anchor" href="#on-the-frontend" aria-label="Permalink to &quot;On the frontend&quot;">​</a></h2><p>When an Entry has multiple published rates, a rate selector appears in the <a href="./availability-search-component">availability search component</a> so visitors can choose which rate to book. The selected rate flows through to the <a href="./availability-results">availability results</a>, which show the price, availability, and cancellation label for the chosen rate.</p><p>If no rate is selected and an Entry has several rates, Resrv shows the cheapest available rate by default.</p><h2 id="upgrading-from-v5" tabindex="-1">Upgrading from v5 <a class="header-anchor" href="#upgrading-from-v5" aria-label="Permalink to &quot;Upgrading from v5&quot;">​</a></h2><p>If you are coming from v5, where multiple availability options were handled through &quot;Advanced availability&quot; properties and &quot;Connected availabilities&quot;, see <a href="./upgrading">Upgrading to v6</a> for the full migration sequence and the <code>resrv:upgrade-to-rates</code> command that converts your existing setup into rates.</p>',45);function c(p,g,u,b,f,y){const t=o("Image");return i(),n("div",null,[l,a(t,{src:"./img/resrv-rates-list.webp",alt:"The Rates management page with the collection picker and rate tree."}),d,a(t,{src:"./img/resrv-rates-panel.webp",alt:"The Add/Edit rate panel with its General, Pricing, Availability and Restrictions sections."}),h])}const w=r(s,[["render",c]]);export{v as __pageData,w as default};
